begin;
select plan(6);
select lives_ok($scenario$ do $$
declare uid uuid:='11111111-1111-4111-8111-111111111111'; uid2 uuid:='33333333-3333-4333-8333-333333333333'; uid3 uuid:='44444444-4444-4444-8444-444444444444'; tid uuid:='22222222-2222-4222-8222-222222222222'; ta uuid; tb uuid; pa uuid; pb uuid; gi uuid; ti uuid; ri uuid; cap_ti uuid; cap_ri uuid; refid uuid; tok text; i int; gcount int;
begin
 insert into auth.users(id,aud,role,email) values(uid,'authenticated','authenticated','m1-acceptance@example.invalid'),(uid2,'authenticated','authenticated','m1-acceptance-second@example.invalid'),(uid3,'authenticated','authenticated','m1-outsider@example.invalid');
 insert into public.tournaments(id,slug,name,created_by,status) values(tid,'m1-acceptance','M1 Acceptance',uid,'published');
 insert into public.tournaments(slug,name,created_by,status) values('m1-draft','M1 Draft',uid,'draft');
 insert into public.tournaments(slug,name,created_by,status) values('m1-other','Other organizer tournament',uid2,'draft');
 insert into public.teams(tournament_id,name,short_name) values(tid,'Alpha','ALP') returning id into ta;
 insert into public.teams(tournament_id,name,short_name) values(tid,'Beta','BET') returning id into tb;
 insert into public.players(tournament_id,team_id,full_name) values(tid,ta,'Player Alpha') returning id into pa;
 insert into public.players(tournament_id,team_id,full_name) values(tid,tb,'Player Beta') returning id into pb;
 insert into public.tournament_groups(tournament_id,name) values(tid,'Group A') returning id into gi;
 insert into public.ties(tournament_id,stage,group_id,round_label,team_a_id,team_b_id) values(tid,'group',gi,'Pool round 1',ta,tb) returning id into ti;
 if (select count(*) from public.rubbers where tie_id=ti)<>5 then raise exception 'tie trigger did not create five rubbers'; end if;
 select r.id into ri from public.rubbers r where r.tie_id=ti and r.position=1;
 insert into public.referees(tournament_id,name) values(tid,'Acceptance Referee') returning id into refid;
 select token into tok from public.referee_tokens where referee_id=refid;
 update public.rubbers set referee_id=refid where id=ri;
 insert into public.rubber_players(tournament_id,rubber_id,side,player_id) values(tid,ri,'a',pa),(tid,ri,'b',pb);
 begin insert into public.rubber_players(tournament_id,rubber_id,side,player_id) values(tid,ri,'a',pb); raise exception 'wrong-team lineup unexpectedly accepted'; exception when others then if sqlerrm<>'player_wrong_team' then raise; end if; end;
 begin perform public.start_rubber(ri,'wrong-token'); raise exception 'invalid token unexpectedly accepted'; exception when others then if sqlerrm<>'forbidden' then raise; end if; end;
 perform public.start_rubber(ri,tok);
 begin perform public.start_rubber((select id from public.rubbers where tie_id=ti and position=2),tok); raise exception 'referee scored an unassigned rubber'; exception when others then if sqlerrm<>'forbidden' then raise; end if; end;
 if not exists(select 1 from public.referee_whoami(tok) where referee_id=refid) then raise exception 'valid referee token failed'; end if;
 perform public.score_point(ri,'a',tok); perform public.undo_point(ri,'a',tok);
 if exists(select 1 from public.games where rubber_id=ri and score_a<>0) then raise exception 'undo did not revert point'; end if;
 for i in 1..19 loop perform public.score_point(ri,'b',tok); end loop;
 for i in 1..21 loop perform public.score_point(ri,'a',tok); end loop;
 for i in 1..19 loop perform public.score_point(ri,'a',tok); end loop;
 for i in 1..21 loop perform public.score_point(ri,'b',tok); end loop;
 for i in 1..20 loop perform public.score_point(ri,'a',tok); perform public.score_point(ri,'b',tok); end loop;
 for i in 1..2 loop perform public.score_point(ri,'a',tok); end loop;
 select count(*) into gcount from public.games where rubber_id=ri and winner_side is not null;
 if gcount<>3 or not exists(select 1 from public.rubbers where id=ri and status='finished' and games_won_a=2 and games_won_b=1) then raise exception 'rubber final score incorrect'; end if;
 perform set_config('request.jwt.claim.sub',uid::text,true);
 perform public.add_organizer_by_email(tid,'m1-outsider@example.invalid');
 if not exists(select 1 from public.tournament_organizers where tournament_id=tid and user_id=uid3) then raise exception 'organizer was not added'; end if;
 perform public.end_rubber_walkover((select id from public.rubbers where tie_id=ti and position=2),'a');
 perform public.end_rubber_walkover((select id from public.rubbers where tie_id=ti and position=3),'a');
 if not exists(select 1 from public.ties where id=ti and status='finished' and winner_team_id=ta) or exists(select 1 from public.rubbers where tie_id=ti and status='scheduled') then raise exception 'tie did not finish and skip remaining rubbers'; end if;
 if not exists(select 1 from public.group_standings where group_id=gi and team_id=ta and played=1 and won=1 and points=1 and rubbers_for=3 and rubbers_against=0) then raise exception 'group standings did not calculate tie totals'; end if;
 insert into public.ties(tournament_id,stage,round_label,team_a_id,team_b_id) values(tid,'group','Cap test',ta,tb) returning id into cap_ti;
 select id into cap_ri from public.rubbers where tie_id=cap_ti and position=1;
 update public.rubbers set referee_id=refid where id=cap_ri;
 insert into public.rubber_players(tournament_id,rubber_id,side,player_id) values(tid,cap_ri,'a',pa),(tid,cap_ri,'b',pb);
 perform public.start_rubber(cap_ri,tok);
 for i in 1..29 loop perform public.score_point(cap_ri,'a',tok); perform public.score_point(cap_ri,'b',tok); end loop;
 perform public.score_point(cap_ri,'a',tok);
 if not exists(select 1 from public.games where rubber_id=cap_ri and score_a=30 and score_b=29 and winner_side='a') then raise exception '29-29 cap rule failed'; end if;
 perform public.end_rubber_early(cap_ri,'b',tok);
 if not exists(select 1 from public.rubbers where id=cap_ri and status='finished' and winner_side='b' and end_reason='retired') then raise exception 'early finish RPC failed'; end if;
 perform public.finish_tournament(tid);
 if exists(select 1 from public.referees where tournament_id=tid) then raise exception 'finish_tournament did not remove referees'; end if;
 begin perform public.referee_whoami(tok); raise exception 'old token unexpectedly resolved'; exception when others then if sqlerrm<>'invalid_token' then raise; end if; end;
end $$ $scenario$, 'referee scoring, organizer RPCs, tie completion and token invalidation work');
select ok(not has_table_privilege('anon','public.referee_tokens','select') and not has_table_privilege('anon','public.games','insert'), 'anon cannot read secret tokens or insert games');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
set local role authenticated;
update public.tournaments set name='Unauthorized change' where slug='m1-acceptance';
reset role;
select is((select name from public.tournaments where slug='m1-acceptance'),'M1 Acceptance','another organizer cannot update this tournament');
reset request.jwt.claim.sub;
set local role anon;
select is((select count(*)::int from public.tournaments),1,'anon sees published tournaments but not drafts');
reset role;
select throws_ok($$delete from public.tournament_organizers where tournament_id=(select id from public.tournaments where slug='m1-other') and user_id='33333333-3333-4333-8333-333333333333'::uuid$$, 'P0001', 'last_organizer', 'cannot delete the final organizer');
select lives_ok($$delete from public.tournaments where slug='m1-other'$$, 'deleting a tournament cascades organizer rows');
select * from finish();
rollback;
